import subprocess
import sys

def get_user_info(username):
    try:
        # تنفيذ الأمر getent passwd <username>
        result = subprocess.run(
            ['getent', 'passwd', username],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False  # لا نرفع استثناء عند الفشل
        )

        # التحقق من نجاح التنفيذ
        if result.returncode == 0:
            # إرجاع الإخراج بنجاح
            return result.stdout.strip()
        else:
            # إرجاع رسالة خطأ إذا لم يكن المستخدم موجودًا أو فشل الأمر
            error_msg = result.stderr.strip() or "User not found or command failed."
            return f"Error: {error_msg}"

    except Exception as e:
        # معالجة أي استثناءات غير متوقعة
        return f"Exception occurred: {str(e)}"

def main():
    # قراءة اسم المستخدم من المدخلات القياسية (stdin)
    try:
        username = input().strip()
        if not username:
            print("Error: No username provided.", file=sys.stderr)
            sys.exit(1)

        # الحصول على معلومات المستخدم
        output = get_user_info(username)

        # طباعة الإخراج في stdout
        print(output)

    except KeyboardInterrupt:
        print("\nOperation interrupted by user.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

